parameters.jsCode:
// 1. Leer la salida estructurada del LLM
const llm = $input.first().json.output || {};
const webhook = $node["Webhook Ingesta Web"]?.json?.body || {};

// 2. Tabla de especialistas (regla de negocio, NO la decide la IA)
const especialistas = {
  redes: "Roberto Salas",
  software: "María Brenes",
  hardware: "Carlos Méndez",
  base_datos: "Esteban Rojas",
  seguridad: "Ana Lucía Gómez",
  otro: "Jorge Ulloa"
};

// 3. Asignación fija: una categoría = un especialista
const operador = especialistas[llm.categoria] || especialistas["otro"];

// 4. Validaciones
const errores = [];
const categoriasOk = ["redes", "software", "hardware", "base_datos", "seguridad", "otro"];
const criticidadOk = ["alta", "media", "baja"];

if (!categoriasOk.includes(llm.categoria)) errores.push("categoria invalida");
if (!criticidadOk.includes(llm.criticidad)) errores.push("criticidad invalida");
if (typeof llm.confidence !== "number") errores.push("confidence ausente");
if (!llm.resumen) errores.push("resumen ausente");

const correo = webhook.correo || webhook.email || "";
const correoValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(correo);
if (!correoValido) errores.push("correo del cliente ausente o invalido");

const valido = errores.length === 0;

// 5. Salida normalizada
return [{
  json: {
    id_tiquete: "TKT-" + Date.now(),
    correo: correoValido ? correo : "",
    mensaje_original: webhook.mensaje || "",
    categoria: llm.categoria || "otro",
    criticidad: llm.criticidad || "media",
    motivo_criticidad: llm.motivo_criticidad || "",
    usuarios_afectados: llm.usuarios_afectados || "no_encontrado",
    duracion_minutos: llm.duracion_minutos || "no_encontrado",
    diagnostico: llm.diagnostico || "causa no determinada",
    resumen: llm.resumen || "",
    confidence: typeof llm.confidence === "number" ? llm.confidence : 0,
    operador: operador,
    estado: valido ? "Abierto" : "Revisión manual",
    valido: valido,
    errores_validacion: errores.join("; "),
    fecha_creacion: new Date().toISOString()
  }
}];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "categoria": {
      "type": "string",
      "enum": ["redes", "software", "hardware", "base_datos", "seguridad", "otro"],
      "description": "Área técnica a la que pertenece el problema reportado"
    },
    "criticidad": {
      "type": "string",
      "enum": ["alta", "media", "baja"],
      "description": "Nivel de urgencia según el impacto reportado"
    },
    "motivo_criticidad": {
      "type": "string",
      "description": "Frase corta que justifica la criticidad asignada"
    },
    "usuarios_afectados": {
      "type": "string",
      "description": "Cantidad de usuarios afectados según el mensaje, o 'no_encontrado'"
    },
    "duracion_minutos": {
      "type": "string",
      "description": "Duración del problema en minutos según el mensaje, o 'no_encontrado'"
    },
    "diagnostico": {
      "type": "string",
      "description": "Causa probable del problema en una frase"
    },
    "resumen": {
      "type": "string",
      "description": "Resumen del ticket en máximo 2 oraciones"
    },
    "confidence": {
      "type": "number",
      "description": "Confianza global entre 0 y 1"
    }
  },
  "required": ["categoria", "criticidad", "motivo_criticidad", "usuarios_afectados", "duracion_minutos", "diagnostico", "resumen", "confidence"]
}
